const $=s=>document.querySelector(s),rub=n=>Math.round(n).toLocaleString('ru-RU')+' ₽';
const shops=[['Пятёрочка','5','#dc3b3e'],['Магнит','М','#d92d36'],['Лента','Л','#174eaa'],['Перекрёсток','П','#218447'],['Ашан','А','#e44242']];
// Demo pack prices in RUB. Quantities are grams; eggs are edible grams (10 eggs ≈ 500 g).
const products={oats:['Овсяные хлопья',500,370,[69,75,79,89,72]],milk:['Молоко 2,5%',1000,52,[89,85,92,99,86]],apple:['Яблоки',1000,52,[139,129,149,159,119]],rice:['Рис',900,344,[99,109,105,119,98]],buckwheat:['Гречка',800,343,[89,85,95,109,82]],chicken:['Куриное филе',1000,113,[399,389,419,449,379]],carrot:['Морковь',1000,35,[49,45,55,59,42]],onion:['Лук',1000,41,[49,45,52,59,43]],cabbage:['Капуста',1000,27,[45,49,55,59,42]],oil:['Масло подсолнечное',900,899,[129,119,139,149,125]],egg:['Яйца, 10 шт.',500,157,[109,99,119,129,105]],potato:['Картофель',1000,77,[69,65,75,79,62]],lentil:['Чечевица',450,310,[115,109,119,139,105]],pasta:['Макароны',450,350,[59,65,69,79,55]],curd:['Творог 5%',200,121,[79,85,89,99,75]]};
const recipes=[
{name:'Овсяная каша с яблоком',time:15,ing:{oats:85,milk:230,apple:180,oil:4},steps:['Залейте хлопья молоком и небольшим количеством воды.','Варите на слабом огне 7–10 минут, помешивая.','Нарежьте яблоко, добавьте в кашу вместе с маслом.']},
{name:'Гречка с курицей и овощами',time:35,ing:{buckwheat:120,chicken:190,carrot:90,onion:50,oil:20},steps:['Промойте гречку, залейте водой 1:2 и варите около 20 минут.','Нарежьте курицу и овощи. Обжарьте лук и морковь с маслом.','Добавьте курицу и немного воды, тушите до полной готовности.','Подавайте с гречкой.']},
{name:'Тёплый салат с чечевицей',time:30,ing:{lentil:120,cabbage:160,carrot:80,egg:100,oil:18},steps:['Промойте чечевицу и отварите до мягкости по инструкции на упаковке.','Отварите яйца вкрутую. Нашинкуйте капусту и морковь.','Слегка потушите овощи с маслом и водой.','Смешайте с чечевицей, сверху выложите нарезанные яйца.']},
{name:'Омлет с картофелем',time:25,ing:{egg:150,potato:240,milk:100,oil:12,apple:130},steps:['Нарежьте картофель небольшими кубиками и отварите до мягкости.','Взбейте яйца с молоком. Выложите картофель на сковороду с маслом.','Залейте яичной смесью, готовьте под крышкой до готовности. Яблоко подайте отдельно.']},
{name:'Куриный плов с морковью',time:40,ing:{rice:120,chicken:180,carrot:120,onion:60,oil:20},steps:['Нарежьте курицу, морковь и лук. Обжарьте в масле.','Добавьте промытый рис и воду примерно в соотношении 1:2.','Тушите под крышкой 20–25 минут до готовности риса и курицы.']},
{name:'Макароны с овощным рагу',time:25,ing:{pasta:125,lentil:50,carrot:100,onion:60,cabbage:130,oil:18},steps:['Отварите чечевицу и макароны отдельно по инструкции.','Потушите измельчённые овощи с маслом и небольшим количеством воды.','Соедините с чечевицей и макаронами, прогрейте 2 минуты.']},
{name:'Творог с яблоком и овсянкой',time:10,ing:{curd:220,oats:60,apple:180,milk:100},steps:['Залейте хлопья горячим молоком и оставьте на 5–7 минут.','Нарежьте яблоко. Разомните творог вилкой.','Смешайте всё в миске. При желании подавайте яблоко отдельно.']},
{name:'Курица с картофелем в духовке',time:50,ing:{chicken:200,potato:380,carrot:120,onion:70,oil:20},steps:['Нарежьте картофель и овощи, смешайте с маслом.','Выложите в форму вместе с курицей, добавьте немного воды.','Запекайте при 190 °C около 40 минут до полной готовности курицы.']},
{name:'Гречка с яйцом и капустой',time:25,ing:{buckwheat:120,egg:130,cabbage:180,onion:50,oil:18},steps:['Отварите гречку. Яйца сварите вкрутую и нарежьте.','Потушите капусту с луком и маслом до мягкости.','Смешайте с гречкой и яйцом.']}
];
const schedule=[[0,1,2],[3,4,5],[0,7,8],[6,1,5],[3,4,2],[0,7,8],[6,1,2]],days=['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'],short=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],shares=[.3,.4,.3];
let members=[2000,1800],selected=[0,1,2],budget=5000,day=0,view='menu',plan,checked=new Set();
const kcal=r=>Object.entries(r.ing).reduce((n,[k,g])=>n+g*products[k][2]/100,0);
function price(k,stores){const p=products[k];let best=stores[0];for(const s of stores)if(p[3][s]<p[3][best])best=s;return {shop:best,price:p[3][best]}}
function buildPlan(b,people,stores,cheap=false){const totalKcal=people.reduce((a,b)=>a+b,0),menu=cheap?schedule.map(row=>[0,row[1]===7?4:1,5]):schedule;let need={};let meals=menu.map((row,d)=>row.map((id,m)=>{const recipe=recipes[id],factor=totalKcal*shares[m]/kcal(recipe);let cost=0;for(const [k,g]of Object.entries(recipe.ing)){need[k]=(need[k]||0)+g*factor;cost+=g*factor/products[k][1]*price(k,stores).price}return{id,factor,cost,kcal:totalKcal*shares[m]}}));const basket=Object.entries(need).map(([k,g])=>{const p=products[k],chosen=price(k,stores),packs=Math.ceil(g/p[1]);return{k,name:p[0],grams:g,packs,size:p[1],...chosen,cost:packs*chosen.price}});return{budget:b,people:[...people],stores:[...stores],totalKcal,meals,basket,total:basket.reduce((n,p)=>n+p.cost,0),cheap}}
function calculate(){let normal=buildPlan(budget,members,selected);if(normal.total>budget){let economy=buildPlan(budget,members,selected,true);if(economy.total<normal.total)normal=economy}plan=normal;checked.clear();render();}
function renderPeople(){$('#people-count').textContent=members.length+' чел.';$('#people').innerHTML=members.map((n,i)=>`<div class="person"><span class="avatar">${String(i+1).padStart(2,'0')}</span><label for="person-${i}">Человек ${i+1}</label><input aria-label="Ккал в день, человек ${i+1}" id="person-${i}" type="number" min="500" max="6000" step="50" value="${n}" required>${members.length>1?`<button class="remove" type="button" data-remove="${i}" aria-label="Удалить человека ${i+1}">×</button>`:''}</div>`).join('');$('#add').disabled=members.length>=8}
$('#stores').innerHTML=shops.map((s,i)=>`<label class="store"><span class="store-logo" style="background:${s[2]}">${s[1]}</span>${s[0]}<input type="checkbox" value="${i}" ${selected.includes(i)?'checked':''} aria-label="${s[0]}"></label>`).join('');
function readMembers(){return members.map((_,i)=>Number($('#person-'+i).value))}
$('#add').onclick=()=>{members=readMembers();if(members.length<8)members.push(2000);renderPeople();dirty()};$('#people').onclick=e=>{if(e.target.dataset.remove!==undefined){members=readMembers();members.splice(Number(e.target.dataset.remove),1);renderPeople();dirty()}};
function dirty(){$('#form-message').textContent='Параметры изменены — нажмите «Составить рацион».'}
$('#settings').oninput=dirty;document.querySelectorAll('[data-budget]').forEach(b=>b.onclick=()=>{$('#budget').value=b.dataset.budget;dirty()});
$('#settings').onsubmit=e=>{e.preventDefault();let stores=[...document.querySelectorAll('#stores input:checked')].map(x=>Number(x.value));if(!stores.length){$('#form-message').textContent='Выберите хотя бы один магазин.';return}members=readMembers();selected=stores;budget=Number($('#budget').value);calculate();$('#form-message').textContent='Рацион пересчитан по вашим параметрам.';if(innerWidth<761)$('#summary').scrollIntoView({behavior:'smooth',block:'start'})};
function render(){const left=plan.budget-plan.total;$('#summary').innerHTML=`<div class="stat"><label>Корзина на неделю</label><strong>${rub(plan.total)}</strong><div class="progress"><i style="width:${Math.min(100,plan.total/plan.budget*100)}%"></i></div><small>из ${rub(plan.budget)} · целые упаковки</small></div><div class="stat"><label>${left>=0?'Останется в бюджете':'Не хватает'}</label><strong class="${left<0?'over':''}">${rub(Math.abs(left))}</strong><small>${left>=0?'Можно оставить про запас':'Попробуйте увеличить бюджет'}</small></div><div class="stat"><label>В день на человека</label><strong>${rub(plan.total/7/plan.people.length)}</strong><small>${plan.people.length} чел. · ${plan.totalKcal.toLocaleString('ru-RU')} ккал/день на семью</small></div>`;$('#basket-count').textContent=plan.basket.length;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='menu')renderMenu();else renderShopping()}
function renderMenu(){$('#content').innerHTML=`<div class="days">${short.map((s,i)=>`<button class="day ${day===i?'active':''}" data-day="${i}" aria-pressed="${day===i}"><b>${s}</b>День ${i+1}</button>`).join('')}</div><div class="daily-heading"><h2>${days[day]}</h2><span>3 приёма пищи · ${plan.cheap?'экономный вариант':'домашнее меню'}</span></div><div class="meals">${plan.meals[day].map((m,i)=>`<article class="meal" tabindex="0" role="button" aria-label="Рецепт: ${recipes[m.id].name}" data-meal="${i}"><div class="meal-art no-photo"><span>${['01','02','03'][i]}</span><span class="meal-label">${['ЗАВТРАК','ОБЕД','УЖИН'][i]}</span></div><div class="meal-body"><h3>${recipes[m.id].name}</h3><div class="meal-meta">${recipes[m.id].time} мин · ${Math.round(m.kcal)} ккал на семью</div><div class="meal-footer"><strong>≈ ${rub(m.cost)}</strong><span>Рецепт ↗</span></div></div></article>`).join('')}</div><div class="portion-note"><span>◷</span><div><b>У каждого — своя порция.</b> ${plan.people.map((p,i)=>`Человек ${i+1}: ${p} ккал/день`).join(' · ')}.<br>Цена блюда — стоимость использованных продуктов. Корзина учитывает целые упаковки и остатки.</div></div>`;document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=Number(b.dataset.day);renderMenu()});document.querySelectorAll('[data-meal]').forEach(b=>{b.onclick=()=>openRecipe(Number(b.dataset.meal));b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.click()}}});addFoodPhoto()}
function addFoodPhoto(){const meal=document.querySelectorAll('.meal-art')[1];if(!meal)return;const img=new Image();img.alt='Пример подачи: курица с гречкой и овощами';img.onload=()=>{meal.querySelector(':scope > span').replaceWith(img);meal.classList.remove('no-photo')};img.src='food.jpg'}
function renderShopping(){$('#content').innerHTML=`<div class="daily-heading"><h2>Корзина на 7 дней</h2><button class="export" id="export">Скачать список ↓</button></div><p class="shopping-intro">Для каждого продукта выбран самый дешёвый демонстрационный вариант в отмеченных сетях. Остатки упаковок остаются дома. Масло включено; вода не учитывается, специи — по желанию.</p>${plan.stores.map(s=>{let rows=plan.basket.filter(p=>p.shop===s);if(!rows.length)return '';return `<div class="section-label"><h3 class="shopping-store">${shops[s][0]} · демоцены</h3><span>${rub(rows.reduce((n,p)=>n+p.cost,0))}</span></div>${rows.map(p=>`<label class="shopping-row"><input type="checkbox" data-product="${p.k}" ${checked.has(p.k)?'checked':''}><span style="flex:1">${p.name}<small style="display:block">${p.packs} уп. × ${p.size} г · нужно ≈ ${Math.round(p.grams)} г</small></span><strong>${rub(p.cost)}</strong></label>`).join('')}`}).join('')}`;document.querySelectorAll('[data-product]').forEach(c=>c.onchange=()=>{if(c.checked)checked.add(c.dataset.product);else checked.delete(c.dataset.product)});$('#export').onclick=()=>{const txt='НА НЕДЕЛЮ — ДЕМОНСТРАЦИОННЫЕ ЦЕНЫ\n'+plan.basket.map(p=>`${p.name}: ${p.packs} уп. × ${p.size} г — ${shops[p.shop][0]}, ${rub(p.cost)}`).join('\n')+'\nИтого: '+rub(plan.total);const url=URL.createObjectURL(new Blob(['\ufeff'+txt],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Покупки на неделю.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
function openRecipe(i){const m=plan.meals[day][i],r=recipes[m.id];$('#recipe-content').innerHTML=`<div class="eyebrow">${days[day].toUpperCase()} · ${r.time} МИНУТ</div><h2>${r.name}</h2><p>На всю семью · ≈ ${rub(m.cost)} · ${Math.round(m.kcal)} ккал</p><h3>Ингредиенты до приготовления</h3><ul>${Object.entries(r.ing).map(([k,g])=>`<li>${products[k][0]} — ${Math.round(g*m.factor)} г</li>`).join('')}</ul><h3>Как приготовить</h3><ol>${r.steps.map(t=>`<li>${t}</li>`).join('')}</ol><h3>Как разделить готовое блюдо</h3><p>${plan.people.map((p,j)=>`Человек ${j+1}: ${(p/plan.totalKcal*100).toFixed(1)}% блюда, ≈ ${Math.round(p*shares[i])} ккал`).join('<br>')}</p><p class="hint">Взвесьте готовое блюдо и разделите по долям. Калорийность примерная, веса яиц указаны без скорлупы.</p>`;$('#recipe').showModal()}
$('.close').onclick=()=>$('#recipe').close();$('#recipe').onclick=e=>{if(e.target===$('#recipe'))$('#recipe').close()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});renderPeople();calculate();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true}};
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'calculate_weekly_menu',description:'Пересчитать недельный рацион с демонстрационными ценами.',inputSchema:{type:'object',properties:{budget:{type:'number',minimum:1,maximum:1000000},calories:{type:'array',items:{type:'number',minimum:500,maximum:6000},minItems:1,maxItems:8},stores:{type:'array',items:{type:'integer',minimum:0,maximum:4},minItems:1}},required:['budget','calories','stores'],additionalProperties:false},execute:input=>{if(!Number.isFinite(input.budget)||input.budget<1||input.budget>1000000||!Array.isArray(input.calories)||input.calories.length<1||input.calories.length>8||input.calories.some(n=>!Number.isFinite(n)||n<500||n>6000)||!Array.isArray(input.stores)||!input.stores.length||input.stores.some(n=>!Number.isInteger(n)||n<0||n>4))throw Error('Некорректные параметры');budget=input.budget;members=[...input.calories];selected=[...new Set(input.stores)];$('#budget').value=budget;renderPeople();document.querySelectorAll('#stores input').forEach(c=>c.checked=selected.includes(Number(c.value)));calculate();return{total:plan.total,budget,withinBudget:plan.total<=budget,demonstrationPrices:true}},annotations:{readOnlyHint:false}})}catch{}}
